84: // ══ TITLE ═══════════════════════════════════════════════════════════════════
85: function buildTitleUnits() {
86:   const specs = [
87:     ['wolf', 'bear', 3, 'Ancient Grimhide'],
88:     ['drake', 'falcon', 4, 'Mythic Embertalon'],
89:     ['serpent', 'mantis', 3, 'Ancient Venomblade'],
90:   ];
91:   return specs.map(([a, b, tier, name]) => {
92:     const u = makeBaseUnit(a, { secondary: b, tier });
93:     u.name = name;
94:     u.art = buildArt(a, b, tier);
95:     return u;
96:   });
97: }
98: let titleUnits = buildTitleUnits();
99: 
100: function renderTitleBest() {
101:   els.bestTitle.textContent = S.best > 0 ? roman(S.best) : '—';
102: }
103: 
104: // ══ STATE HELPERS ═══════════════════════════════════════════════════════════
105: function newRoster() {
106:   resetIds();
107:   const roster = [];
108:   for (const key of STARTING_ROSTER) {
109:     const u = makeBaseUnit(key);
110:     u.name = uniqueName(u.name, roster);
111:     roster.push(u);
112:   }
113:   return roster;
114: }
115: 
116: function rollShop(wave) {
117:   const keys = Object.keys(SPECIES);
118:   const picked = [];
119:   while (picked.length < 3) {
120:     const k = keys[Math.floor(Math.random() * keys.length)];
121:     if (!picked.includes(k)) picked.push(k);
122:   }
123:   const cost = 5 + Math.ceil(wave / 2);
124:   return picked.map((species) => ({ species, cost, sold: false }));
125: }
126: 
127: function buildEnemyPreview(wave) {
128:   const wd = waveData(wave);
129:   return (wd.enemies || []).map((e) => ({ unit: makeEnemyUnit(e, wave), lane: e.lane, row: e.row }));
130: }
