132: function startRun() {
133:   sound.init();
134:   sound.ui();
135:   S.screen = 'run';
136:   S.phase = 'prep';
137:   S.wave = 1;
138:   S.essence = START_ESSENCE;
139:   S.roster = newRoster();
140:   S.slots = {};
141:   S.selectedId = null;
142:   S.hover = null;
143:   S.battle = null;
144:   S.resultShown = false;
145:   S.speed = 1;
146:   S.battleLog = [];
147:   S.stats = { splices: 0, kills: 0 };
148:   S.chipEls = [];
149:   S.abilityUnits = [];
150:   S.shop = rollShop(1);
151:   S.enemyPreview = buildEnemyPreview(1);
152:   S.lastEssence = S.essence;
153:   els.title.classList.add('hidden');
154:   els.app.setAttribute('aria-hidden', 'false');
155:   closeModal();
156:   refreshAll();
157:   showBanner(`WAVE ${roman(1)} · ${waveData(1).name.toUpperCase()}`, 'DEPLOY YOUR BEASTS', '');
158: }
