160: function returnToTitle() {
161:   if (S.resultTimer) clearTimeout(S.resultTimer);
162:   S.screen = 'title';
163:   S.phase = 'prep';
164:   S.battle = null;
165:   S.roster = [];
166:   S.slots = {};
167:   S.abilityUnits = [];
168:   S.chipEls = [];
169:   closeModal();
170:   els.app.setAttribute('aria-hidden', 'true');
171:   els.title.classList.remove('hidden');
172:   renderTitleBest();
173:   titleUnits = buildTitleUnits();
174:   hideOverlays();
