188: // ══ TOP BAR ═════════════════════════════════════════════════════════════════
189: function renderTopbar() {
190:   const total = WAVES.length;
191:   const endless = S.wave > total;
192:   const pips = [];
193:   for (let i = 1; i <= Math.max(total, 8); i++) {
194:     const boss = !!(WAVES[i - 1] && WAVES[i - 1].boss);
195:     const cls = [`wp-pip`];
196:     if (i < S.wave || (endless && i <= total)) cls.push('done');
197:     if (i === S.wave) cls.push('current');
198:     if (boss) cls.push('boss');
199:     pips.push(`<span class="${cls.join(' ')}" title="Wave ${i}${boss ? ' · Boss' : ''}"></span>`);
200:   }
201:   els.waveProgress.innerHTML = `
202:     <span class="wp-label">WAVE <b>${endless ? '∞' : roman(S.wave)}</b> / ${total}</span>
203:     <span class="wp-pips">${pips.join('')}</span>
204:     ${endless ? `<span class="wp-label">ENDLESS +${S.wave - total}</span>` : ''}
205:   `;
206:   els.essenceVal.textContent = S.essence;
207:   if (S.essence !== S.lastEssence) {
208:     els.essenceVal.classList.remove('pop');
209:     void els.essenceVal.offsetWidth;
210:     els.essenceVal.classList.add('pop');
211:     S.lastEssence = S.essence;
212:   }
213:   els.nexusPair.style.opacity = S.screen === 'run' ? 1 : 0;
214: }
215: 
216: function updateNexusBars() {
217:   const b = S.battle;
218:   const you = b ? b.playerNexus : NEXUS_HP;
219:   const foe = b ? b.enemyNexus : NEXUS_HP;
220:   els.nexusYouFill.style.width = `${(you / NEXUS_HP) * 100}%`;
221:   els.nexusFoeFill.style.width = `${(foe / NEXUS_HP) * 100}%`;
222:   els.nexusYouVal.textContent = Math.ceil(you);
223:   els.nexusFoeVal.textContent = Math.ceil(foe);
224: }
