226: // ══ SIDEBAR · PREP ══════════════════════════════════════════════════════════
227: function enemyRow(e) {
228:   const u = e.unit;
229:   const sp = SPECIES[u.primary];
230:   const traits = traitList(u).slice(0, 3).map((t) =>
231:     `<span class="mini-trait" style="--tc:${t.color}" data-tip="${esc(t.desc)}" data-tip-title="${esc(t.icon + ' ' + t.name)}">${t.icon}</span>`).join('');
232:   const tier = Array.from({ length: u.tier }, () => '<i class="tier-dot"></i>').join('');
233:   return `<div class="enemy-row">
234:     <span class="lane-badge">${laneName(e.lane)}</span>
235:     <div class="er-main">
236:       <div class="er-name">${esc(u.name)}</div>
237:       <div class="er-meta"><span>${e.row.toUpperCase()}</span><span>·</span><span>${esc(sp.name)}${u.secondary ? ' / ' + esc(SPECIES[u.secondary].name) : ''}</span><span class="tier-dots">${tier}</span></div>
238:     </div>
239:     <div class="er-traits">${traits}</div>
240:   </div>`;
241: }
