243: function renderPrepSidebar() {
244:   const wd = waveData(S.wave);
245:   const isBoss = !!wd.boss;
246:   const endless = S.wave > WAVES.length;
247:   const enrolled = S.roster.length;
248:   const deployed = Object.values(S.slots).filter(Boolean).length;
249:   const bossTag = isBoss ? `<span class="boss-tag">◆ BOSS ENCOUNTER</span>` : '';
250:   const offers = S.shop.map((o, i) => {
251:     const sp = SPECIES[o.species];
252:     const traits = sp.traits.map((t) => `<span class="mini-trait" style="--tc:${TRAITS[t].color}" data-tip="${esc(TRAITS[t].desc)}" data-tip-title="${esc(TRAITS[t].icon + ' ' + TRAITS[t].name)}">${TRAITS[t].icon}</span>`).join('');
253:     const disabled = o.sold || S.roster.length >= ROSTER_MAX || S.essence < o.cost;
254:     return `<div class="shop-card ${o.sold ? 'sold' : ''}">
255:       <canvas data-shop-portrait="${i}" width="38" height="38"></canvas>
256:       <div class="sc-main">
257:         <div class="sc-name">${esc(sp.name)}</div>
258:         <div class="sc-meta">${esc(sp.role)} · ${sp.stats.range >= 150 ? 'RANGED' : 'MELEE'}</div>
259:         <div class="sc-traits">${traits}</div>
260:       </div>
261:       <button class="buy-btn" data-action="buy" data-index="${i}" ${disabled ? 'disabled' : ''} title="${o.sold ? 'Already purchased' : S.roster.length >= ROSTER_MAX ? 'Roster full' : `Recruit ${sp.name}`}">
262:         ${o.sold ? 'ADDED' : `<span class="gem"></span>${o.cost}`}
263:       </button>
264:     </div>`;
265:   }).join('');
266: 
267:   const recruitHint = S.roster.length >= ROSTER_MAX
268:     ? 'Your roster is full. Splice two beasts into one to make room.'
269:     : S.essence < 5 ? 'Spend essence on recruits, or splice what you already own.'
270:       : 'Recruits arrive at Tier I. Splice them to unlock higher tiers.';
271: 
272:   const tip = S.wave === 1
273:     ? '<b>Start here:</b> pick a beast from the roster below, then click a glowing rune in a lane. Melee beasts belong in FRONT, casters and healers in BACK. Then splice two beasts to create something new.'
274:     : `<b>Tactics:</b> ranged beasts cover adjacent lanes. A lane with no defender will breach your nexus. ${wd.boss ? 'The boss is enormously tough — stack one lane and focus it down.' : 'Match your tanks against their damage.'}`;
275: 
276:   els.sidebar.innerHTML = `
277:     <section class="panel ${isBoss ? 'boss-panel' : ''}">
278:       <div class="eyebrow"><span>WAVE <b>${endless ? '∞' : roman(S.wave)}</b> / ${WAVES.length}</span><span class="dot"></span><span>${isBoss ? 'BOSS' : endless ? 'ENDLESS' : 'TRIAL'}</span></div>
279:       <h2 class="wave-name">${esc(wd.name)}</h2>
280:       <div class="wave-sub">${esc(wd.subtitle)}</div>
281:       <p class="wave-desc">${esc(wd.desc)}</p>
282:       ${bossTag}
283:       <div class="intel-head">ENEMY LINEUP <span>${wd.enemies.length} BEASTS · ${wd.boss ? 'DANGER' : 'SCOUTED'}</span></div>
284:       <div class="enemy-list">${S.enemyPreview.map(enemyRow).join('')}</div>
285:     </section>
286: 
287:     <section class="panel shop-panel">
288:       <div class="shop-head"><div class="shop-title">THE BLACK MARKET</div><small>RECRUIT · COST ${5 + Math.ceil(S.wave / 2)} ◆</small></div>
289:       <div class="shop-offers">${offers}</div>
290:       <div class="shop-foot">
291:         <button class="reroll-btn" data-action="reroll" ${S.essence < 2 ? 'disabled' : ''}>↻ REROLL OFFERS · 2 ◆</button>
292:         <small>${recruitHint.split('.')[0]}.</small>
293:       </div>
294:     </section>
295: 
296:     <div class="deploy-count"><span>DEPLOYED</span><b>${deployed} / 8</b></div>
297:     <div class="tip-box">${tip}</div>
298:     <button class="btn btn-gold battle-btn" data-action="battle" ${deployed === 0 ? 'disabled' : ''}>
299:       BEGIN BATTLE <span class="kbd">SPACE</span>
300:     </button>
301:   `;
302:   drawSidebarPortraits();
303:   updateEssenceButtons();
304: }
