306: function drawSidebarPortraits() {
307:   els.sidebar.querySelectorAll('[data-shop-portrait]').forEach((c) => {
308:     const i = Number(c.dataset.shopPortrait);
309:     const offer = S.shop[i];
310:     if (!offer) return;
311:     const art = buildArt(offer.species, null, 1);
312:     drawPortrait(c, { art }, 38);
313:   });
314: }
315: 
316: function updateEssenceButtons() {
317:   els.sidebar.querySelectorAll('[data-action="buy"]').forEach((btn) => {
318:     const i = Number(btn.dataset.index);
319:     const offer = S.shop[i];
320:     if (!offer) return;
321:     btn.disabled = offer.sold || S.roster.length >= ROSTER_MAX || S.essence < offer.cost;
322:   });
323: }
