325: // ══ SIDEBAR · BATTLE ════════════════════════════════════════════════════════
326: function renderBattleSidebar() {
327:   const wd = S.battle ? S.battle.waveData : waveData(S.wave);
328:   els.sidebar.innerHTML = `
329:     <section class="panel battle-side">
330:       <div class="bs-header">
331:         <span class="bs-wave">${esc(wd.name)}</span>
332:         <span class="bs-timer" id="bsTimer">0:60</span>
333:       </div>
334:       <div class="battle-stats">
335:         <div class="bstat"><small>WAVE</small><b>${S.wave > WAVES.length ? '∞' : roman(S.wave)}</b></div>
336:         <div class="bstat"><small>YOUR NEXUS</small><b id="bstatYou">${NEXUS_HP}</b></div>
337:         <div class="bstat"><small>FOE NEXUS</small><b id="bstatFoe">${NEXUS_HP}</b></div>
338:       </div>
339:       <div class="auto-note"><b>COMMAND:</b> abilities charge automatically. Click a ready beast in the command deck — or press its number — to fire it early. Unused abilities auto-cast after 6 seconds.</div>
340:       <div class="panel log-panel">
341:         <div class="log-title">BATTLE FEED <span>LIVE</span></div>
342:         <div class="log-list" id="logList"></div>
343:       </div>
344:       <div class="tip-box"><b>Tip:</b> break a lane to send your beast into their nexus. Ranged beasts cover adjacent lanes — position them behind a wall.</div>
345:     </section>
346:   `;
347:   renderLog();
348: }
349: 
350: function pushLog(text, tone = '', icon = '•') {
351:   S.battleLog.push({ text, tone, icon });
352:   if (S.battleLog.length > 40) S.battleLog.shift();
353:   renderLog();
354: }
355: 
356: function renderLog() {
357:   const list = $('#logList');
358:   if (!list) return;
359:   list.innerHTML = S.battleLog.map((l) =>
360:     `<div class="log-line ${l.tone}"><i>${l.icon}</i><span>${l.text}</span></div>`).join('');
361: }
362: 
363: // ══ DOCK · ROSTER ═══════════════════════════════════════════════════════════
364: function slotLabelFor(unitId) {
365:   for (const [key, id] of Object.entries(S.slots)) {
366:     if (id === unitId) {
367:       const [lane, row] = key.split('-');
368:       return `${laneName(Number(lane))} · ${row.toUpperCase()[0]}`;
369:     }
370:   }
371:   return null;
372: }
373: 
374: function unitTip(u) {
375:   const t = traitList(u).map((x) => `${x.name}: ${x.desc}`).join(' ');
376:   const ab = ABILITIES[u.ability];
377:   return `${speciesLine(u)} · Tier ${u.tier} ${u.role}. HP ${u.stats.hp} · ATK ${u.stats.atk} · SPD ${u.stats.interval}s · ${statTags(u).range}. ${t} Ability — ${ab.name}: ${ab.desc}`;
378: }
379: 
380: function traitMiniHtml(u) {
381:   return traitList(u).map((t) =>
382:     `<span class="mini-trait" style="--tc:${t.color}" data-tip="${esc(t.desc)}" data-tip-title="${esc(t.icon + ' ' + t.name)}">${t.icon}</span>`).join('');
383: }
384: 
385: function renderRosterDock() {
386:   const deployedCount = Object.values(S.slots).filter(Boolean).length;
387:   els.dockHead.innerHTML = `
388:     <div class="dock-title">
389:       <h3>YOUR ROSTER</h3>
390:       <span class="count"><b>${S.roster.length}</b> / ${ROSTER_MAX}</span>
391:       <span class="dock-tip">Click a beast, then a glowing rune. Click a placed beast again to recall.</span>
392:     </div>
393:     <div class="dock-actions">
394:       <button class="btn btn-sm btn-splice" data-action="open-splice" ${S.roster.length < 2 ? 'disabled' : ''}>◆ SPLICE BEASTS</button>
395:       <button class="btn btn-sm btn-primary" data-action="battle" ${deployedCount === 0 ? 'disabled' : ''}>BATTLE <span class="kbd">␣</span></button>
396:     </div>
397:   `;
398: 
399:   if (!S.roster.length) {
400:     els.dockBody.innerHTML = '<div class="empty-note">Your roster is empty.</div>';
401:     return;
402:   }
403:   els.dockBody.innerHTML = S.roster.map((u) => {
404:     const slot = slotLabelFor(u.id);
405:     const sel = S.selectedId === u.id;
406:     return `<button class="unit-card ${sel ? 'selected' : ''} ${slot ? 'deployed' : ''}" data-uid="${u.id}" data-tier="${u.tier}" data-tip="${esc(unitTip(u))}" data-tip-title="${esc(u.name + ' · ' + speciesLine(u))}">
407:       <div class="uc-top">
408:         <span class="uc-tier">${'<i></i>'.repeat(u.tier)}</span>
409:         <span class="uc-deploy">${slot || ''}</span>
410:       </div>
411:       <canvas class="uc-art" data-portrait="${u.id}"></canvas>
412:       <div class="uc-name">${esc(u.name)}</div>
413:       <div class="uc-line">${esc(speciesLine(u))}</div>
414:       <div class="uc-traits">${traitMiniHtml(u)}</div>
415:       <div class="uc-bottom">
416:         <span class="uc-stat">HP <b>${u.stats.hp}</b></span>
417:         <span class="uc-stat">ATK <b>${u.stats.atk}</b></span>
418:       </div>
419:     </button>`;
420:   }).join('');
421:   els.dockBody.querySelectorAll('[data-portrait]').forEach((c) => {
422:     const u = S.roster.find((x) => x.id === c.dataset.portrait);
423:     if (u) drawPortrait(c, u, 58);
424:   });
425: }
