427: // ══ DOCK · BATTLE COMMAND ══════════════════════════════════════════════════
428: function renderBattleDock() {
429:   S.abilityUnits = S.battle ? S.battle.units.filter((u) => u.side === 'player') : [];
430:   els.dockHead.innerHTML = `
431:     <div class="dock-title">
432:       <h3>COMMAND DECK</h3>
433:       <span class="count"><b>${S.abilityUnits.length}</b> BEASTS DEPLOYED</span>
434:       <span class="dock-tip">Press 1–8 or click a charged beast. Abilities fire automatically after 6s if unused.</span>
435:     </div>
436:     <div class="dock-actions">
437:       <span class="count" id="battleKills">0 SLAIN</span>
438:     </div>
439:   `;
440:   if (!S.abilityUnits.length) {
441:     els.dockBody.innerHTML = '<div class="empty-note">No beasts deployed.</div>';
442:     S.chipEls = [];
443:     return;
444:   }
445:   els.dockBody.innerHTML = S.abilityUnits.map((u, i) => {
446:     const ab = ABILITIES[u.ability];
447:     return `<button class="ability-chip" data-uid="${u.ref.id}" data-index="${i}">
448:       <span class="ac-key">${i + 1}</span>
449:       <span class="ac-lane">${laneName(u.lane)} · ${u.row[0].toUpperCase()}</span>
450:       <canvas data-chip-portrait="${u.ref.id}"></canvas>
451:       <span class="ac-name">${esc(u.name)}</span>
452:       <span class="ac-skill">${esc(ab.name)}</span>
453:       <span class="ac-charge"><i></i></span>
454:       <span class="ac-state">0%</span>
455:     </button>`;
456:   }).join('');
457:   S.chipEls = S.abilityUnits.map((u, i) => {
458:     const root = els.dockBody.querySelector(`[data-index="${i}"]`);
459:     return {
460:       u,
461:       root,
462:       fill: root ? root.querySelector('.ac-charge i') : null,
463:       state: root ? root.querySelector('.ac-state') : null,
464:     };
465:   });
466:   els.dockBody.querySelectorAll('[data-chip-portrait]').forEach((c) => {
467:     const u = S.abilityUnits.find((x) => x.ref.id === c.dataset.chipPortrait);
468:     if (u) drawPortrait(c, u.ref, 54);
469:   });
470: }
