472: function updateBattleDock() {
473:   if (!S.battle) return;
474:   let ready = 0;
475:   for (const chip of S.chipEls) {
476:     const u = chip.u;
477:     if (!u || !chip.root) continue;
478:     const charged = u.energy >= 100;
479:     const alive = u.alive;
480:     if (alive) chip.fill.style.width = `${Math.min(100, u.energy)}%`;
481:     chip.root.classList.toggle('ready', alive && charged);
482:     chip.root.classList.toggle('dead', !alive);
483:     chip.root.classList.toggle('stunned', alive && u.status.stunUntil > S.battle.time);
484:     let txt;
485:     if (!alive) txt = 'SLAIN';
486:     else if (u.status.stunUntil > S.battle.time) txt = 'STUNNED';
487:     else if (charged) {
488:       const auto = autoCastIn(S.battle, u);
489:       txt = auto != null && auto > 0 ? `AUTO ${Math.ceil(auto)}s` : 'READY';
490:       if (alive) ready++;
491:     } else txt = `${Math.floor(u.energy)}%`;
492:     if (chip.state.textContent !== txt) chip.state.textContent = txt;
493:   }
494:   const killEl = $('#battleKills');
495:   if (killEl) {
496:     const kills = S.battle.units.filter((u) => u.side === 'enemy' && !u.alive).length;
497:     killEl.textContent = `${kills} SLAIN`;
498:   }
499:   const el = $('#bsTimer');
500:   if (el) {
501:     const left = Math.max(0, S.battle.duration - S.battle.time);
502:     el.textContent = `0:${String(Math.ceil(left)).padStart(2, '0')}`;
503:   }
504:   const y = $('#bstatYou'); if (y) y.textContent = Math.ceil(S.battle.playerNexus);
505:   const f = $('#bstatFoe'); if (f) f.textContent = Math.ceil(S.battle.enemyNexus);
506: }
