605: function deployUnit(id, key) {
606:   const unit = S.roster.find((u) => u.id === id);
607:   if (!unit) return;
608:   let fromKey = null;
609:   for (const [k, v] of Object.entries(S.slots)) if (v === id) { fromKey = k; break; }
610:   const occupant = S.slots[key];
611:   if (fromKey === key) return;
612:   if (occupant && occupant !== id) {
613:     if (fromKey) S.slots[fromKey] = occupant;
614:     else delete S.slots[fromKey];
615:   } else if (fromKey) {
616:     delete S.slots[fromKey];
617:   }
618:   S.slots[key] = id;
619:   sound.deploy();
620:   refreshAll();
621: }
