714: function handleBattleEvents(events) {
715:   let needsResult = false;
716:   for (const e of events) {
717:     switch (e.type) {
718:       case 'hit':
719:         sound.hit();
720:         if (e.crit) sound.heavy();
721:         break;
722:       case 'slash': sound.hit(); break;
723:       case 'shot': sound.shot(); break;
724:       case 'cast': {
725:         sound.cast();
726:         const ab = ABILITIES[e.ability];
727:         if (e.side === 'enemy') {
728:           pushLog(`<b>${esc(e.name || 'Enemy')}</b> casts ${esc(ab.name)}.`, 'cast', '✦');
729:         }
730:         break;
731:       }
732:       case 'death': {
733:         sound.death();
734:         if (e.side === 'enemy') {
735:           S.stats.kills++;
736:           if (e.tier >= 3) toast(`${e.name} has fallen`, 'epic');
737:         }
738:         if (e.side === 'player') pushLog(`<b>${esc(e.name)}</b> is slain.`, 'death', '✕');
739:         else pushLog(`<b>${esc(e.name)}</b> falls.`, 'death', '✕');
740:         break;
741:       }
742:       case 'laneBreak': {
743:         if (e.side === 'player') {
744:           sound.alarm();
745:           showBanner(`LANE ${laneName(e.lane)} BREACHED`, 'YOUR BEAST IS STRIKING THE ENEMY NEXUS', 'gold', 1800);
746:           pushLog(`Lane ${laneName(e.lane)} breached — enemy nexus under attack!`, 'breach', '⚡');
747:         } else {
748:           sound.alarm();
749:           showBanner(`LANE ${laneName(e.lane)} LOST`, 'THE ENEMY IS STRIKING YOUR NEXUS', 'foe', 1800);
750:           pushLog(`Lane ${laneName(e.lane)} has fallen. Your nexus is exposed!`, 'breach', '⚡');
751:         }
752:         break;
753:       }
754:       case 'nexus': {
755:         sound.nexus();
756:         arena.shake = Math.max(arena.shake, 8);
757:         break;
758:       }
759:       case 'bloodrush': {
760:         sound.bloodrush();
761:         showBanner('BLOODRUSH', 'THE ARENA HUNGERS · ALL DAMAGE INCREASED', 'foe', 2600);
762:         pushLog('<b>The Bloodrush begins.</b> All beasts grow stronger.', 'breach', '☠');
763:         break;
764:       }
765:       case 'end': {
766:         needsResult = true;
767:         if (e.winner === 'player') sound.victory(); else sound.defeat();
768:         showBanner(e.winner === 'player' ? 'NEXUS BROKEN' : 'NEXUS LOST', e.winner === 'player' ? 'THE RITE CONTINUES' : 'THE ARENA CLAIMS YOU', e.winner === 'player' ? 'gold' : 'foe', 2400);
769:         break;
770:       }
771:       default: break;
772:     }
773:   }
774:   updateBattleDock();
775:   if (needsResult && !S.resultShown) {
776:     S.resultShown = true;
777:     if (S.resultTimer) clearTimeout(S.resultTimer);
778:     const token = S.battle;
779:     S.resultTimer = setTimeout(() => {
780:       if (S.screen === 'run' && S.battle === token) showResult(token.winner);
781:     }, 1500);
782:   }
783: }
