787:   S.phase = 'result';
788:   const wd = S.battle.waveData;
789:   const victory = winner === 'player';
790:   const reward = victory ? wd.reward : 0;
791:   const kills = S.battle.units.filter((u) => u.side === 'enemy' && !u.alive).length;
792:   const survivors = S.battle.units.filter((u) => u.side === 'player' && u.alive).length;
793:   const time = Math.min(60, Math.round(S.battle.time));
794:   if (victory) {
795:     S.essence += reward;
796:     S.best = Math.max(S.best, S.wave);
797:     localStorage.setItem('chimera-front-best', String(S.best));
798:   }
799:   updateNexusBars();
800:   updateOverlays();
801:   setTimeout(() => { if (S.screen === 'run') renderTitleBest(); }, 0);
