803:   const newBest = victory && S.wave >= S.best;
804:   const isEndless = S.wave > WAVES.length;
805:   const resultStats = `
806:     <div class="rs"><small>WAVE</small><b>${isEndless ? '∞ ' + (S.wave - WAVES.length) : roman(S.wave)}</b></div>
807:     <div class="rs"><small>TIME</small><b>${time}s</b></div>
808:     <div class="rs"><small>BEASTS SLAIN</small><b>${kills}</b></div>
809:     <div class="rs"><small>SURVIVORS</small><b>${survivors}</b></div>
810:     <div class="rs"><small>SPLICES</small><b>${S.stats.splices}</b></div>
811:     <div class="rs"><small>NEXUS LEFT</small><b>${Math.ceil(S.battle.playerNexus)}</b></div>
812:   `;
813:   const actions = victory
814:     ? `<button class="btn btn-ghost" data-action="title">END RUN</button>
815:        <button class="btn btn-gold" data-action="next-wave">${S.wave >= 8 ? 'ENTER THE ENDLESS' : 'NEXT WAVE'} <span class="btn-arrow">›</span></button>`
816:     : `<button class="btn btn-ghost" data-action="title">RETURN TO TITLE</button>
817:        <button class="btn btn-primary" data-action="retry">TRY AGAIN <span class="btn-arrow">›</span></button>`;
818: 
819:   openModal(`
820:     <div class="modal result-modal ${victory ? 'win' : 'loss'}">
821:       <div class="modal-body">
822:         <div class="result-emblem"><span>${victory ? '◆' : '✕'}</span></div>
823:         <div class="result-kicker">${victory ? `WAVE ${isEndless ? 'ENDLESS' : roman(S.wave)} CLEARED` : 'THE RITE ENDS'}</div>
824:         <div class="result-title">${victory ? (S.wave === WAVES.length ? 'THE HOLLOW KING FALLS' : 'VICTORY') : 'DEFEAT'}</div>
825:         <p class="result-sub">${victory
826:           ? (S.wave >= WAVES.length ? 'The arena is silent. Its oldest hunger is finally fed.' : 'The enemy nexus shatters. Your chimeras taste blood and victory.')
827:           : `Your nexus broke on wave ${isEndless ? 'endless' : roman(S.wave)}. The rite begins again.`}</p>
828:         ${victory ? `<div class="result-reward"><span class="gem"></span>+${reward} ESSENCE ${newBest ? ' · NEW BEST WAVE' : ''}</div>` : ''}
829:         <div class="result-stats">${resultStats}</div>
830:         <div class="result-actions">${actions}</div>
831:       </div>
832:     </div>
833:     <div class="modal-backdrop" data-action="close-result" style="position:absolute"></div>
834:   `, true);
835:   // Put backdrop behind
836:   const root = els.modalRoot;
837:   const bd = root.querySelector('.modal-backdrop');
838:   const md = root.querySelector('.modal');
