875: function splicePreviewHtml() {
876:   const a = findRoster(S.spliceSel[0]);
877:   const b = findRoster(S.spliceSel[1]);
878:   if (!a || !b || a === b) {
879:     return `<div class="splice-empty">
880:       <div class="se-rune"><span>✧</span></div>
881:       <h3>THE SPLICE CHAMBER</h3>
882:       <p>Choose two beasts. The first chosen becomes the <b>primary form</b> — its body, range and ability dominate. The second contributes essence, coloring and traits.</p>
883:     </div>`;
884:   }
885:   const h = previewSplice(a, b);
886:   const delta = (key) => {
887:     const best = Math.max(a.stats[key], b.stats[key]);
888:     const d = h.stats[key] - best;
889:     return d === 0 ? '' : `<i class="${d < 0 ? 'down' : ''}">${d > 0 ? '+' : ''}${d}</i>`;
890:   };
891:   const stat = (label, value, d = '') => `<div class="sp-stat"><small>${label}</small><b>${value}</b>${d}</div>`;
892:   const ab = ABILITIES[h.ability];
893:   const cost = spliceCost(a, b);
894:   const cannot = S.essence < cost;
895:   return `
896:     <canvas class="sp-art" id="spliceArt"></canvas>
897:     <div class="sp-name">${esc(h.name)}</div>
898:     <div class="sp-lineage">${esc(SPECIES[h.primary].name)} / ${esc(SPECIES[h.secondary].name)} · TIER ${h.tier}</div>
899:     <div class="sp-role">${esc(h.role)} · ${h.stats.range >= 150 ? 'RANGED' : 'MELEE'}</div>
900:     <div class="sp-traits">${h.traits.map((t) => `<span class="trait" style="--tc:${TRAITS[t].color}" data-tip="${esc(TRAITS[t].desc)}" data-tip-title="${esc(TRAITS[t].icon + ' ' + TRAITS[t].name)}">${TRAITS[t].icon} ${TRAITS[t].name}</span>`).join('')}</div>
901:     <div class="sp-stats">
902:       ${stat('HEALTH', h.stats.hp, delta('hp'))}
903:       ${stat('ATTACK', h.stats.atk, delta('atk'))}
904:       ${stat('ATK SPD', h.stats.interval + 's')}
905:       ${stat('FORM', h.stats.range >= 150 ? 'RANGED' : 'MELEE')}
906:     </div>
907:     <div class="sp-ability"><b>${esc(ab.icon)} ${esc(ab.name)}</b><span>${esc(ab.desc)}</span></div>
908:     <input type="hidden" data-cost="${cost}" data-cannot="${cannot ? 1 : 0}" />
909:   `;
