933:       ${a ? `<div class="parent-row"><canvas data-mini-parent="${a.id}"></canvas><div><div class="pr-name">${esc(a.name)}</div><div class="pr-tag">${esc(SPECIES[a.primary].name)} · ${a.stats.range >= 150 ? 'RANGED' : 'MELEE'} · ability</div></div></div>` : `<div class="ob-sub">— choose the form —</div>`}
934:     </div>
