316:     for (let i = 0; i < 7; i++) {
317:       ctx.beginPath(); ctx.moveTo(24, 60 + i * 82); ctx.lineTo(976, 60 + i * 82);
318:       ctx.strokeStyle = 'rgba(120,190,230,.03)'; ctx.lineWidth = 1; ctx.stroke();
319:     }
320:     // center sigil
321:     ctx.save(); ctx.translate(500, 320);
322:     ctx.rotate(t * 0.03);
323:     ctx.strokeStyle = 'rgba(120,230,230,.055)';
324:     ctx.lineWidth = 1.2;
325:     for (const r of [96, 106, 150]) { ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke(); }
326:     for (let i = 0; i < 8; i++) {
327:       const a = i * Math.PI / 4;
328:       ctx.beginPath();
329:       ctx.moveTo(Math.cos(a) * 106, Math.sin(a) * 106);
330:       ctx.lineTo(Math.cos(a) * 150, Math.sin(a) * 150);
331:       ctx.stroke();
332:     }
333:     ctx.font = '700 13px Cinzel, serif';
334:     ctx.fillStyle = 'rgba(120,220,230,.065)';
335:     ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
336:     ctx.fillText('THE SPLICING PIT', 0, 0);
337:     ctx.restore();
338:     ctx.restore();
339: 
340:     // horizontal lanes (player left → enemy right)
341:     for (let lane = 0; lane < 5; lane++) {
342:       const y = LANE_Y[lane];
343:       const laneGrad = ctx.createLinearGradient(36, 0, 964, 0);
344:       laneGrad.addColorStop(0, 'rgba(95,227,209,.055)');
345:       laneGrad.addColorStop(0.46, 'rgba(140,200,255,.016)');
346:       laneGrad.addColorStop(1, 'rgba(255,92,108,.05)');
347:       rr(ctx, 34, y - 52, 932, 104, 14);
348:       ctx.fillStyle = laneGrad; ctx.fill();
349:       ctx.strokeStyle = 'rgba(150,215,255,.06)'; ctx.lineWidth = 1; ctx.stroke();
350: 
351:       // lane divider runes
352:       for (let i = 0; i < 6; i++) {
353:         const x = 170 + i * 132;
354:         ctx.save(); ctx.translate(x, y + 46); ctx.rotate(Math.PI / 4);
355:         ctx.fillStyle = 'rgba(120,230,230,.10)';
356:         ctx.fillRect(-2, -2, 4, 4);
357:         ctx.restore();
358:       }
359:       // lane numeral near your gate
360:       ctx.save();
361:       ctx.font = '700 13px Cinzel, serif';
362:       ctx.fillStyle = 'rgba(150,225,235,.28)';
363:       ctx.textAlign = 'center';
364:       ctx.fillText(LANE_ROMAN[lane], 94, y + 5);
365:       ctx.restore();
366:     }
367: 
368:     // center divider (no-man's land)
369:     ctx.save();
370:     ctx.setLineDash([3, 12]);
371:     ctx.beginPath(); ctx.moveTo(500, 40); ctx.lineTo(500, 580);
372:     ctx.strokeStyle = 'rgba(160,230,255,.09)'; ctx.lineWidth = 1; ctx.stroke();
373:     ctx.restore();
