375:     // player column headers
376:     ctx.save();
377:     ctx.font = '600 8px Rajdhani, sans-serif';
378:     ctx.fillStyle = 'rgba(120,210,200,.32)';
379:     ctx.textAlign = 'center';
380:     ctx.fillText('BACK', SLOT_X.player.back, 612);
381:     ctx.fillText('FRONT', SLOT_X.player.front, 612);
382:     ctx.restore();
