384:     // corner braziers
385:     this.drawBrazier(ctx, 62, 42, t, '#ffb35c');
386:     this.drawBrazier(ctx, 938, 42, t, '#ffb35c');
387:     this.drawBrazier(ctx, 62, 580, t, '#63f0d8');
388:     this.drawBrazier(ctx, 938, 580, t, '#63f0d8');
389: 
390:     // gates
391:     this.drawGate(ctx, 'enemy', t, battle);
392:     this.drawGate(ctx, 'player', t, battle);
393: 
394:     // ambient motes
395:     for (const m of this.motes) {
396:       ctx.globalAlpha = 0.24 + Math.sin(t * 1.4 + m.ph) * 0.16;
397:       ctx.fillStyle = m.hue;
398:       ctx.beginPath(); ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2); ctx.fill();
399:     }
