402:     // edge vignette
403:     const vg = ctx.createRadialGradient(500, 300, 220, 500, 300, 600);
404:     vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(2,4,8,.5)');
405:     ctx.fillStyle = vg; ctx.fillRect(0, 0, 1000, 620);
