408:   drawBrazier(ctx, x, y, t, color) {
409:     ctx.save();
410:     ctx.translate(x, y);
411:     // bowl
412:     ctx.beginPath(); ctx.moveTo(-11, 0); ctx.lineTo(11, 0); ctx.lineTo(7, 10); ctx.lineTo(-7, 10); ctx.closePath();
413:     ctx.fillStyle = '#1a2731'; ctx.fill();
414:     ctx.strokeStyle = 'rgba(160,220,240,.2)'; ctx.lineWidth = 1; ctx.stroke();
415:     // flame
416:     const f = Math.sin(t * 7 + x) * 2;
417:     ctx.globalCompositeOperation = 'lighter';
418:     const fg = ctx.createRadialGradient(0, -6, 0, 0, -6, 26);
419:     fg.addColorStop(0, rgba(color, 0.9)); fg.addColorStop(0.35, rgba(color, 0.35)); fg.addColorStop(1, rgba(color, 0));
420:     ctx.fillStyle = fg;
421:     ctx.beginPath(); ctx.ellipse(0, -8, 17 + f, 26 + f, 0, 0, Math.PI * 2); ctx.fill();
422:     ctx.fillStyle = 'rgba(255,245,220,.9)';
423:     ctx.beginPath();
424:     ctx.moveTo(-4, -2); ctx.quadraticCurveTo(-3, -16 - f, 1, -22 - f); ctx.quadraticCurveTo(5, -12, 4, -2); ctx.closePath(); ctx.fill();
425:     ctx.restore();
426:   }
