428:   drawGate(ctx, side, t, battle) {
429:     const gx = GATE_X[side];
430:     const color = TEAM[side];
431:     const isLeft = side === 'player';
432:     const nexus = battle ? (side === 'player' ? battle.playerNexus : battle.enemyNexus) : 120;
433:     const hpFrac = nexus / 120;
434:     const wallX = isLeft ? 20 : 952;
435:     ctx.save();
436:     // side wall band
437:     const g = ctx.createLinearGradient(wallX, 0, wallX + 28, 0);
438:     g.addColorStop(0, isLeft ? '#0e1a26' : '#080d15');
439:     g.addColorStop(1, isLeft ? '#080d15' : '#0e1a26');
440:     ctx.fillStyle = g;
441:     ctx.fillRect(wallX, 22, 28, 576);
442:     ctx.strokeStyle = rgba(color, 0.22); ctx.lineWidth = 1;
443:     ctx.beginPath();
444:     ctx.moveTo(isLeft ? 48 : 952, 22); ctx.lineTo(isLeft ? 48 : 952, 598); ctx.stroke();
445: 
446:     // pylons at each lane
447:     for (let lane = 0; lane < 5; lane++) {
448:       const y = LANE_Y[lane];
449:       const pulse = 0.55 + Math.sin(t * 2.2 + lane) * 0.2 + (1 - hpFrac) * 0.3;
450:       ctx.save();
451:       ctx.translate(gx, y);
452:       ctx.globalCompositeOperation = 'lighter';
453:       const cg = ctx.createRadialGradient(0, 0, 2, 0, 0, 44);
454:       cg.addColorStop(0, rgba(color, 0.55 * pulse));
455:       cg.addColorStop(0.4, rgba(color, 0.16 * pulse));
456:       cg.addColorStop(1, rgba(color, 0));
457:       ctx.fillStyle = cg;
458:       ctx.beginPath(); ctx.arc(0, 0, 44, 0, Math.PI * 2); ctx.fill();
459:       ctx.restore();
460: 
461:       // shrine / crystal
462:       ctx.save(); ctx.translate(gx, y);
463:       ctx.beginPath();
464:       ctx.moveTo(0, -14); ctx.lineTo(11, -3); ctx.lineTo(6, 12); ctx.lineTo(-6, 12); ctx.lineTo(-11, -3); ctx.closePath();
465:       ctx.fillStyle = rgba(color, 0.22 + hpFrac * 0.25); ctx.fill();
466:       ctx.strokeStyle = rgba(color, 0.7); ctx.lineWidth = 1.4; ctx.stroke();
467:       ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(0, 7); ctx.strokeStyle = rgba('#ffffff', 0.45); ctx.lineWidth = 1; ctx.stroke();
468:       ctx.restore();
469:     }
470: 
471:     // vertical label along the wall
472:     ctx.save();
473:     ctx.translate(isLeft ? 14 : 986, 310);
474:     ctx.rotate(isLeft ? -Math.PI / 2 : Math.PI / 2);
475:     ctx.font = '700 9px Rajdhani, sans-serif';
476:     ctx.fillStyle = rgba(color, 0.6);
477:     ctx.textAlign = 'center';
478:     ctx.letterSpacing = '3px';
479:     ctx.fillText(side === 'player' ? 'YOUR NEXUS' : 'ENEMY NEXUS', 0, 0);
480:     ctx.letterSpacing = '0px';
481:     ctx.restore();
482:     ctx.restore();
483:   }
