485:   drawSlot(ctx, x, y, lane, row, side, state, opts = {}) {
486:     const key = `${lane}-${row}`;
487:     const hovered = state.hover && state.hover.key === key;
488:     const selected = state.selectedId && state.slots[key] === state.selectedId;
489:     const occupied = !!state.slots[key];
490:     const isEnemy = side === 'enemy';
491:     const color = isEnemy ? TEAM.enemy : TEAM.player;
492:     ctx.save();
493:     ctx.translate(x, y + 2);
494:     ctx.scale(1, 0.42);
495:     const r = 36;
496:     const pulse = 0.5 + Math.sin(this.time * 2 + lane + (row === 'back' ? 1 : 0)) * 0.12;
497:     const active = hovered || selected || (state.selectedId && !occupied && !isEnemy);
498:     ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2);
499:     ctx.fillStyle = active ? rgba(color, 0.15) : 'rgba(255,255,255,.028)';
500:     ctx.fill();
501:     ctx.strokeStyle = rgba(color, active ? 0.7 : 0.25);
502:     ctx.lineWidth = hovered ? 2.4 : 1.3;
503:     ctx.setLineDash(active ? [] : [5, 7]);
504:     ctx.stroke();
505:     ctx.setLineDash([]);
506:     ctx.beginPath(); ctx.arc(0, 0, r - 7, 0, Math.PI * 2);
507:     ctx.strokeStyle = rgba(color, active ? 0.3 : 0.13); ctx.lineWidth = 1; ctx.stroke();
508:     // inner rune
509:     ctx.rotate(Math.PI / 4);
510:     ctx.strokeStyle = rgba(color, active ? 0.55 : 0.18); ctx.lineWidth = 1;
511:     ctx.strokeRect(-9, -9, 18, 18);
512:     ctx.restore();
513: 
514:     if (active) {
515:       ctx.save();
516:       ctx.globalCompositeOperation = 'lighter';
517:       const glow = ctx.createRadialGradient(x, y, 4, x, y, 58);
518:       glow.addColorStop(0, rgba(color, 0.16)); glow.addColorStop(1, rgba(color, 0));
519:       ctx.fillStyle = glow;
520:       ctx.beginPath(); ctx.arc(x, y, 58, 0, Math.PI * 2); ctx.fill();
521:       ctx.restore();
522:     }
523: 
524:     if (row === 'front' && !isEnemy && !occupied) {
525:       ctx.font = '600 8px Rajdhani, sans-serif';
526:       ctx.fillStyle = 'rgba(140,190,210,.34)';
527:       ctx.textAlign = 'center';
528:       ctx.fillText('FRONT', x, y + 28);
529:     }
530:     if (row === 'back' && !isEnemy && !occupied) {
531:       ctx.font = '600 8px Rajdhani, sans-serif';
532:       ctx.fillStyle = 'rgba(140,190,210,.3)';
533:       ctx.textAlign = 'center';
534:       ctx.fillText('BACK', x, y + 28);
535:     }
536:   }
