538:   drawHpBar(ctx, u, y, small = false) {
539:     const w = small ? 48 : 62;
540:     const h = small ? 4 : 5.5;
541:     const x = u.x - w / 2;
542:     const frac = clamp(u.hp / u.maxHp, 0, 1);
543:     const color = frac > 0.55 ? '#6ee7a8' : frac > 0.28 ? '#f4c96b' : '#ff6d7e';
544:     ctx.save();
545:     rr(ctx, x - 1, y - 1, w + 2, h + 2, (h + 2) / 2);
546:     ctx.fillStyle = 'rgba(4,8,12,.82)'; ctx.fill();
547:     ctx.strokeStyle = 'rgba(0,0,0,.6)'; ctx.lineWidth = 1; ctx.stroke();
548:     if (frac > 0) {
549:       rr(ctx, x, y, Math.max(1.5, w * frac), h, h / 2);
550:       ctx.fillStyle = color; ctx.fill();
551:       rr(ctx, x, y, Math.max(1.5, w * frac), h / 2, h / 2);
552:       ctx.fillStyle = 'rgba(255,255,255,.22)'; ctx.fill();
553:     }
554:     if (u.shield > 0) {
555:       const sw = w * clamp(u.shield / u.maxHp, 0, 1);
556:       rr(ctx, x, y - 3, sw, 2, 1);
557:       ctx.fillStyle = '#9fc4ff'; ctx.fill();
558:     }
559:     // tier pips
560:     const team = u.side === 'player' ? TEAM.player : TEAM.enemy;
561:     for (let i = 0; i < u.tier; i++) {
562:       diamond(ctx, x - 8 - i * 7, y + h / 2, 2.2);
563:       ctx.fillStyle = i === 0 ? team : 'rgba(240,200,121,.8)'; ctx.fill();
564:     }
565:     // status
566:     let sx = x + w + 6;
567:     const dot = (c) => { ctx.beginPath(); ctx.arc(sx, y + h / 2, 2.4, 0, Math.PI * 2); ctx.fillStyle = c; ctx.fill(); sx += 6; };
568:     if (u.poison && u.poison.length) dot('#b8ef6a');
569:     if (u.burn) dot('#ff9a5c');
570:     if (u.status && u.status.slowUntil > this.time) dot('#9be8ff');
571:     if (u.status && u.status.stunUntil > this.time) dot('#ffd46e');
572:     if (u.status && u.status.atkBuffUntil > this.time) dot('#ffcf6e');
573:     ctx.restore();
574:   }
