576:   drawUnit(ctx, u, state, scaleMul = 1, preview = false) {
577:     const art = u.ref.art;
578:     const scale = 0.78 * (art.scale || 1) * scaleMul;
579:     const dir = u.side === 'player' ? -1 : 1;
580:     const lunge = preview ? 0 : (u.lunge || 0) * 6 * dir;
581:     const alpha = u.alive === false ? 0.25 : 1;
582:     const x = u.x;
583:     const y = u.y + lunge;
584:     drawCreature(ctx, art, x, y, scale, {
585:       time: this.time,
586:       seed: (u.lane + 1) * 1.7 + (u.side === 'enemy' ? 2.3 : 0),
587:       team: u.side,
588:       flash: u.flash || 0,
589:       alpha,
590:       ring: true,
591:       bob: u.walking ? 1.6 : 0.8,
592:     });
593: 
594:     if (preview) return;
595: 
596:     // energy ring at feet
597:     if (u.energy != null) {
598:       const pct = clamp(u.energy / 100, 0, 1);
599:       const color = u.side === 'player' ? TEAM.player : TEAM.enemy;
600:       ctx.save();
601:       ctx.translate(x, y + 3); ctx.scale(1, 0.4);
602:       ctx.beginPath();
603:       ctx.arc(0, 0, 27, -Math.PI / 2, -Math.PI / 2 + pct * Math.PI * 2);
604:       ctx.strokeStyle = u.energy >= 100 ? '#ffe08a' : rgba(color, 0.7);
605:       ctx.lineWidth = 2.4;
606:       if (u.energy >= 100) { ctx.shadowColor = '#ffe08a'; ctx.shadowBlur = 8; }
607:       ctx.stroke();
608:       ctx.restore();
609:     }
610: 
611:     // shield ring
612:     if (u.shield > 0) {
613:       ctx.save();
614:       ctx.translate(x, y - 40);
615:       ctx.strokeStyle = 'rgba(159,196,255,.5)';
616:       ctx.lineWidth = 1.4;
617:       hexPath(ctx, 0, 0, 33 + Math.sin(this.time * 3) * 2);
618:       ctx.stroke();
619:       ctx.restore();
620:     }
621: 
622:     // stun stars
623:     if (u.status && u.status.stunUntil > this.time) {
624:       ctx.save();
625:       for (let i = 0; i < 3; i++) {
626:         const a = this.time * 3 + i * 2.1;
627:         const sx = x + Math.cos(a) * 22;
628:         const sy = y - 74 + Math.sin(a) * 5;
629:         ctx.fillStyle = 'rgba(255,225,140,.9)';
630:         diamond(ctx, sx, sy, 2.4); ctx.fill();
631:       }
632:       ctx.restore();
633:     }
634: 
635:     // ready halo
636:     if (u.energy >= 100) {
637:       ctx.save();
638:       ctx.globalCompositeOperation = 'lighter';
639:       const rg = ctx.createRadialGradient(x, y - 60, 6, x, y - 60, 42);
640:       rg.addColorStop(0, 'rgba(255,224,138,.22)'); rg.addColorStop(1, 'rgba(255,224,138,0)');
641:       ctx.fillStyle = rg;
642:       ctx.beginPath(); ctx.arc(x, y - 60, 42, 0, Math.PI * 2); ctx.fill();
643:       ctx.restore();
644:       ctx.save();
645:       ctx.fillStyle = '#ffe08a';
646:       ctx.shadowColor = '#ffe08a'; ctx.shadowBlur = 8;
647:       diamond(ctx, x, y - 100 - Math.sin(this.time * 3) * 3, 4); ctx.fill();
648:       ctx.restore();
649:     }
650: 
651:     this.drawHpBar(ctx, u, y - (art.feats.has('bulk') ? 88 : 84));
652:   }
