654:   // ══ MAIN RENDER ═══════════════════════════════════════════════════════════
655:   render(state, dt) {
656:     this.updateFx(dt);
657:     const ctx = this.ctx;
658:     const { dpr, w, h, scale, ox, oy } = this.view;
659:     ctx.setTransform(1, 0, 0, 1, 0, 0);
660:     ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
661:     ctx.fillStyle = '#050810';
662:     ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
663: 
664:     const shakeX = this.shake ? rnd(-this.shake, this.shake) : 0;
665:     const shakeY = this.shake ? rnd(-this.shake, this.shake) * 0.6 : 0;
666:     ctx.setTransform(dpr, 0, 0, dpr, dpr * (ox + shakeX * scale), dpr * (oy + shakeY * scale));
667:     ctx.scale(scale, scale);
668:     ctx.save();
669:     ctx.beginPath(); ctx.rect(0, 0, 1000, 620); ctx.clip();
670: 
671:     const t = this.time;
672:     this.drawBackdrop(ctx, t, state);
673: 
674:     // slots
675:     for (let lane = 0; lane < 5; lane++) {
676:       for (const row of ['back', 'front']) {
677:         this.drawSlot(ctx, SLOT_X.player[row], LANE_Y[lane] + LANE_OFF.player[row], lane, row, 'player', state);
678:         this.drawSlot(ctx, SLOT_X.enemy[row], LANE_Y[lane] + LANE_OFF.enemy[row], lane, row, 'enemy', state);
679:       }
680:     }
681: 
682:     if (state.mode === 'prep') {
683:       this.drawPrep(ctx, state, t);
684:     } else if (state.battle) {
685:       this.drawBattle(ctx, state, t);
686:     }
687: 
688:     // floats on top
689:     for (const f of this.floats) {
690:       const a = clamp(f.life / f.max, 0, 1);
691:       ctx.save();
692:       ctx.globalAlpha = a;
693:       ctx.font = `700 ${f.size}px Rajdhani, sans-serif`;
694:       ctx.textAlign = 'center';
695:       ctx.lineWidth = 3;
696:       ctx.strokeStyle = 'rgba(4,8,12,.8)';
697:       ctx.strokeText(f.text, f.x, f.y);
698:       ctx.fillStyle = f.color;
699:       ctx.fillText(f.text, f.x, f.y);
700:       ctx.restore();
701:     }
702: 
703:     // vignette over units for cohesion
704:     const vg = ctx.createRadialGradient(500, 310, 300, 500, 310, 590);
705:     vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(2,4,8,.28)');
706:     ctx.fillStyle = vg; ctx.fillRect(0, 0, 1000, 620);
707: 
708:     if (this.flashRed > 0.01) {
709:       ctx.fillStyle = `rgba(255,40,60,${this.flashRed * 0.5})`;
710:       ctx.fillRect(0, 0, 1000, 620);
711:     }
712:     for (const f of this.fx.filter((f) => f.type === 'bloodrush')) {
713:       ctx.fillStyle = `rgba(255,40,50,${0.08 + Math.sin(t * 8) * 0.04})`;
714:       ctx.fillRect(0, 0, 1000, 620);
715:     }
716:     ctx.restore();
717:   }
