719:   drawPrep(ctx, state, t) {
720:     // enemy intel
721:     if (state.enemies) {
722:       for (const e of state.enemies) {
723:         const x = SLOT_X.enemy[e.row];
724:         const y = LANE_Y[e.lane] + LANE_OFF.enemy[e.row];
725:         ctx.save(); ctx.globalAlpha = 0.9;
726:         const fake = {
727:           x, y, side: 'enemy', lane: e.lane, row: e.row, ref: e.unit,
728:           flash: 0, walking: false, energy: 0, shield: 0, alive: true,
729:           status: { stunUntil: 0, slowUntil: 0, atkBuffUntil: 0 },
730:           hp: e.unit.stats.hp, maxHp: e.unit.stats.hp, tier: e.unit.tier,
731:         };
732:         this.drawUnit(ctx, fake, state, 0.94, false);
733:         ctx.font = '600 9px Rajdhani, sans-serif';
734:         ctx.textAlign = 'center';
735:         ctx.fillStyle = 'rgba(255,150,160,.85)';
736:         ctx.fillText(e.unit.name.toUpperCase(), x, y + 30);
737:         ctx.restore();
738:       }
739:     }
740: 
741:     // deployed player units
742:     for (const [key, id] of Object.entries(state.slots || {})) {
743:       if (!id) continue;
744:       const [laneS, row] = key.split('-');
745:       const lane = Number(laneS);
746:       const ru = state.roster.find((u) => u.id === id);
747:       if (!ru) continue;
748:       const selected = state.selectedId === id;
749:       const x = SLOT_X.player[row];
750:       const y = LANE_Y[lane] + LANE_OFF.player[row];
751:       const fake = {
752:         x, y, side: 'player', lane, row, ref: ru,
753:         flash: 0, walking: false, energy: 0, shield: 0, alive: true,
754:         status: { stunUntil: 0, slowUntil: 0, atkBuffUntil: 0 },
755:         hp: ru.stats.hp, maxHp: ru.stats.hp, tier: ru.tier,
756:       };
757:       ctx.save();
758:       if (selected) {
759:         ctx.globalCompositeOperation = 'lighter';
760:         const sg = ctx.createRadialGradient(x, y - 24, 4, x, y - 24, 58);
761:         sg.addColorStop(0, 'rgba(95,227,209,.16)'); sg.addColorStop(1, 'rgba(95,227,209,0)');
762:         ctx.fillStyle = sg; ctx.beginPath(); ctx.arc(x, y - 24, 58, 0, Math.PI * 2); ctx.fill();
763:       }
