79: function drawBeast(ctx, a, o) {
80:   const { c1, c2, belly, glow, feats } = a;
81:   const bulk = feats.has('bulk') || a.primary === 'bear' || a.primary === 'rhino';
82:   const wolfish = a.primary === 'wolf' || a.primary === 'lynx' || feats.has('mane');
83:   const outline = shade(c2, -18);
84:   const bw = bulk ? 33 : 26;
85:   const bh = bulk ? 33 : 30;
86: 
87:   // tail
88:   if (feats.has('tail')) {
89:     ctx.save();
90:     const sway = Math.sin(o.time * 2 + o.seed) * 3;
91:     ctx.beginPath();
92:     ctx.moveTo(16, -40);
93:     ctx.bezierCurveTo(38, -36 + sway, 43, -18, 35, -6 + sway);
94:     ctx.strokeStyle = outline; ctx.lineWidth = 13; ctx.lineCap = 'round'; ctx.stroke();
95:     ctx.strokeStyle = c1; ctx.lineWidth = 9; ctx.stroke();
96:     if (wolfish) { E(ctx, 34, -5 + sway, 6, 8, 0.5); fill(ctx, belly); }
97:     ctx.restore();
98:   }
99: 
100:   // rear legs
101:   ell(ctx, -bw * 0.55, -15, bulk ? 13 : 10, 16, c2, 0, outline);
102:   ell(ctx, bw * 0.55, -15, bulk ? 13 : 10, 16, c2, 0, outline);
103:   ell(ctx, -bw * 0.58, -3, 11, 5, shade(c2, 14), 0, outline, 2);
104:   ell(ctx, bw * 0.58, -3, 11, 5, shade(c2, 14), 0, outline, 2);
105: 
106:   // body
107:   E(ctx, 0, -46, bw, bh);
108:   fill(ctx, grad(ctx, -bw, -82, bw, -12, [[0, shade(c1, 26)], [0.55, c1], [1, shade(c2, 6)]]));
109:   stroke(ctx, outline, 3);
110:   // belly
111:   E(ctx, 0, -37, bw * 0.58, bh * 0.56);
112:   fill(ctx, mix(belly, c1, 0.22));
113:   // shoulder shading
114:   E(ctx, -bw * 0.72, -58, 12, 16, 'rgba(255,255,255,.07)', -0.2);
115:   E(ctx, bw * 0.72, -58, 12, 16, 'rgba(0,0,0,.12)', 0.2);
116: 
117:   // mane collar
118:   if (feats.has('mane') || a.primary === 'wolf') {
119:     ctx.beginPath();
120:     for (let i = 0; i <= 10; i++) {
121:       const ang = Math.PI * 0.05 + (i / 10) * Math.PI * 0.9;
122:       const r = i % 2 ? 30 : 23;
123:       const x = Math.cos(ang) * r;
124:       const y = -72 + Math.sin(ang) * r * 0.72;
125:       i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
126:     }
127:     ctx.lineTo(-bw * 0.9, -50); ctx.lineTo(bw * 0.9, -50); ctx.closePath();
128:     fill(ctx, shade(c2, 4));
129:   }
130: 
131:   // arms
132:   const armX = bulk ? 33 : 27;
133:   limb(ctx, [[-armX, -55], [-armX - 4, -34], [-armX - 2, -18]], bulk ? 14 : 10, c1, outline);
134:   limb(ctx, [[armX, -55], [armX + 4, -34], [armX + 2, -18]], bulk ? 14 : 10, c1, outline);
135:   circ(ctx, -armX - 2, -16, bulk ? 8 : 6, shade(c1, -4), outline);
136:   circ(ctx, armX + 2, -16, bulk ? 8 : 6, shade(c1, -4), outline);
137:   if (feats.has('claws') || bulk) {
138:     claws(ctx, -armX - 4, -12, 1, '#e8e2d4', bulk ? 1.2 : 0.9);
139:     claws(ctx, armX + 4, -12, 1, '#e8e2d4', bulk ? 1.2 : 0.9);
140:   }
141: 
142:   // head
143:   const hx = 0, hy = -83;
144:   const hr = bulk ? 23 : 20;
145:   ell(ctx, hx, hy, hr, hr * 0.95, grad(ctx, -hr, hy - hr, hr, hy + hr, [[0, shade(c1, 32)], [1, c1]]), 0, outline, 3);
146: 
147:   // ears
148:   if (feats.has('tuftEars')) {
149:     tri(ctx, [-17, hy - 12], [-25, hy - 33], [-7, hy - 21], c1, outline);
150:     tri(ctx, [17, hy - 12], [25, hy - 33], [7, hy - 21], c1, outline);
151:     E(ctx, -21, hy - 29, 2.6, 6, belly, -0.4); E(ctx, 21, hy - 29, 2.6, 6, belly, 0.4);
152:   } else if (feats.has('ears')) {
153:     tri(ctx, [-15, hy - 10], [-20, hy - 31], [-4, hy - 20], c1, outline);
154:     tri(ctx, [15, hy - 10], [20, hy - 31], [4, hy - 20], c1, outline);
155:     tri(ctx, [-13, hy - 13], [-16, hy - 26], [-7, hy - 19], shade(belly, -14), null);
156:     tri(ctx, [13, hy - 13], [16, hy - 26], [7, hy - 19], shade(belly, -14), null);
157:   }
158: 
159:   // muzzle
160:   ell(ctx, 0, hy + 9, bulk ? 14 : 11, bulk ? 10 : 8.5, shade(belly, -3), 0, outline, 2);
161:   ell(ctx, 0, hy + 6.5, 4.2, 3, DARK);
162:   // mouth / fangs
163:   if (bulk || wolfish) {
164:     ctx.beginPath(); ctx.moveTo(-7, hy + 14); ctx.quadraticCurveTo(0, hy + 17, 7, hy + 14);
165:     ctx.strokeStyle = outline; ctx.lineWidth = 1.6; ctx.stroke();
166:     if (bulk) {
167:       tri(ctx, [-10, hy + 12], [-6, hy + 18], [-4, hy + 12], '#f0e6cf', null);
168:       tri(ctx, [10, hy + 12], [6, hy + 18], [4, hy + 12], '#f0e6cf', null);
169:     }
170:   }
171:   // eyes
172:   eye(ctx, -7.5, hy - 3, 3.4, 3.2, a.eyeL, { rot: -0.15 });
173:   eye(ctx, 7.5, hy - 3, 3.4, 3.2, a.eyeR, { rot: 0.15 });
174:   // brow
175:   ctx.beginPath(); ctx.moveTo(-13, hy - 8); ctx.lineTo(-4, hy - 6); ctx.moveTo(13, hy - 8); ctx.lineTo(4, hy - 6);
176:   ctx.strokeStyle = shade(c2, -8); ctx.lineWidth = 2; ctx.stroke();
177: 
178:   // rhino horn
179:   if (feats.has('horn') || a.primary === 'rhino') {
180:     const hg = grad(ctx, 0, -100, 0, -135, [[0, '#f6dca4'], [1, '#a8794b']]);
181:     ctx.beginPath(); ctx.moveTo(-5, hy + 1); ctx.quadraticCurveTo(-3, hy - 26, 2, hy - 37);
182:     ctx.quadraticCurveTo(8, hy - 20, 7, hy + 2); ctx.closePath(); fill(ctx, hg); stroke(ctx, outline, 2);
183:     ctx.beginPath(); ctx.moveTo(-2, hy - 2); ctx.quadraticCurveTo(0, hy - 22, 2, hy - 31);
184:     ctx.strokeStyle = 'rgba(255,255,255,.4)'; ctx.lineWidth = 2; ctx.stroke();
185:   }
186:   if (feats.has('tusks') && !feats.has('horn')) {
187:     tri(ctx, [-12, hy + 11], [-16, hy + 22], [-8, hy + 14], '#efe3cd', outline, 1.2);
188:     tri(ctx, [12, hy + 11], [16, hy + 22], [8, hy + 14], '#efe3cd', outline, 1.2);
189:   }
190: 
191:   // patterns
192:   if (feats.has('spots')) {
193:     ctx.save(); E(ctx, 0, -46, bw - 1, bh - 1); ctx.clip();
194:     for (let i = 0; i < 7; i++) {
195:       const x = ((i * 37) % 48) - 24; const y = -30 - ((i * 23) % 44);
196:       E(ctx, x, y, 3.5, 2.6, 0.3); fill(ctx, shade(c2, 8));
197:     }
198:     ctx.restore();
199:   }
200:   if (feats.has('plates') && !feats.has('horn')) {
201:     for (let i = 0; i < 3; i++) {
202:       ctx.beginPath(); ctx.moveTo(-bw + 6, -58 + i * 10); ctx.quadraticCurveTo(0, -64 + i * 10, bw - 6, -58 + i * 10);
203:       ctx.strokeStyle = shade(c2, -2); ctx.lineWidth = 4; ctx.stroke();
204:       ctx.strokeStyle = 'rgba(255,255,255,.1)'; ctx.lineWidth = 1; ctx.stroke();
205:     }
206:   }
207:   // glow markings
208:   if (feats.has('runes')) {
209:     ctx.save(); ctx.shadowColor = glow; ctx.shadowBlur = 7;
210:     ctx.strokeStyle = glow; ctx.lineWidth = 1.4; ctx.globalAlpha = 0.85;
211:     for (let i = 0; i < 3; i++) {
212:       const x = -12 + i * 12;
213:       ctx.beginPath(); ctx.moveTo(x, -58); ctx.lineTo(x + 4, -54); ctx.lineTo(x, -49); ctx.stroke();
214:     }
215:     ctx.restore();
216:   }
217:   // accented heterochromia glow flecks from the second lineage
218:   if (a.secondary && a.secondary !== a.primary) {
219:     ctx.save(); ctx.globalAlpha = 0.55; ctx.shadowColor = a.glow; ctx.shadowBlur = 8;
220:     E(ctx, -bw * 0.7, -58, 3, 6, -0.5); fill(ctx, a.glow);
221:     E(ctx, bw * 0.72, -50, 2, 4, 0.6); fill(ctx, a.glow);
222:     ctx.restore();
223:   }
224: }
