284:   ctx.beginPath(); ctx.moveTo(-11, hy - 9); ctx.lineTo(-4, hy - 5); ctx.moveTo(11, hy - 9); ctx.lineTo(4, hy - 5);
285:   ctx.strokeStyle = c2; ctx.lineWidth = 2; ctx.stroke();
